#include <unordered_set>
using namespace std;

// O(n) time | O(n) space - where n is the length of nums
bool zeroSumSubarray(vector<int> nums) {
  unordered_set<int> sums = {0};
  int currentSum = 0;

  for (int num : nums) {
    currentSum += num;
    if (sums.find(currentSum) != sums.end()) {
      return true;
    }
    sums.insert(currentSum);
  } 

  return false;
}

